const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav-links');
function closeMenu(){nav?.classList.remove('open');toggle?.setAttribute('aria-expanded','false');toggle?.setAttribute('aria-label','Open menu')}
toggle?.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close menu':'Open menu')});
nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){closeMenu();toggle?.focus()}});
document.querySelectorAll('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());
document.querySelectorAll('.contact-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const msg=form.querySelector('.form-status');msg.className='form-status';if(!form.reportValidity()){msg.textContent='Please complete the required fields and check your email address.';msg.classList.add('error');return}if(form.dataset.demo==='true'){msg.textContent='Preview complete. No enquiry was sent. This sample can be connected to the business before launch.';msg.classList.add('success')}else{msg.textContent='Your application has not been sent. Enquiry delivery needs to be connected before this form can accept applications.';msg.classList.add('error')}}));
document.querySelectorAll('[data-interest]').forEach(a=>{const u=new URL(a.href,location.origin);u.searchParams.set('interest',a.dataset.interest);a.href=u.href});
const subjectCopy={Maths:['Make the next step make sense.','From a tricky concept to a challenging problem, we work through the thinking and help students understand the why.'],English:['Find the words. Find your voice.','Reading, writing, and expressing an idea clearly. We help students build the skills and confidence to make themselves understood.'],'Study skills':['Build a way of learning that works.','Break big tasks into smaller steps, practise recall, and develop a routine that makes revision feel more manageable.']};
document.querySelectorAll('[data-subject]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-subject]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const copy=subjectCopy[button.dataset.subject],region=document.getElementById('subject-copy');region.querySelector('h3').textContent=copy[0];region.querySelector('p').textContent=copy[1]}));
const sculpture=document.getElementById('sculpture'),world=document.getElementById('sculpture-world');
if(sculpture&&world){const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(pointer:fine)');let frame;const reset=()=>{cancelAnimationFrame(frame);world.style.removeProperty('--rx');world.style.removeProperty('--ry')};sculpture.addEventListener('pointermove',e=>{if(reduced.matches||!fine.matches)return;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const r=sculpture.getBoundingClientRect();world.style.setProperty('--rx',`${5-(e.clientY-r.top-r.height/2)/r.height*10}deg`);world.style.setProperty('--ry',`${-8+(e.clientX-r.left-r.width/2)/r.width*16}deg`)})});sculpture.addEventListener('pointerleave',reset);reduced.addEventListener('change',reset)}

document.addEventListener('click',event=>{if(nav?.classList.contains('open')&&!nav.contains(event.target)&&!toggle.contains(event.target))closeMenu()});
matchMedia('(min-width:801px)').addEventListener('change',closeMenu);
